//! Dynamic option values.
//!
//! Java's options parser passes option values around as `Object`. The Rust port uses [`Value`], a
//! cheaply clonable, type-erased handle; Java `null` is `Option<Value>::None`. Converters build
//! values with [`Value::new`] (scalars) or [`Value::list_of`] / [`Value::list`] (Java
//! `List`s). Field types of options classes implement [`FieldType`], which moves values in and out
//! of the typed struct fields generated by [`crate::options!`].

use std::any::Any;
use std::fmt;
use std::sync::Arc;
use std::time::Duration;

use crate::converter::Converter;
use crate::converters;
use crate::tags::TriState;

/// A value type that can be produced by a converter. `java_to_string` mirrors the Java class's
/// `toString()`, which is observable through `OptionsBase.asMap()`/`cacheKey()`/`toString()`.
pub trait OptionScalar: Any + Clone + fmt::Debug + PartialEq + Send + Sync {
    fn java_to_string(&self) -> String;
}

/// Object-safe view of a value stored in a [`Value`].
pub trait OptionValue: Any + fmt::Debug + Send + Sync {
    fn as_any(&self) -> &dyn Any;
    /// Java `Object.equals`.
    fn dyn_eq(&self, other: &dyn OptionValue) -> bool;
    /// Java `Object.toString`.
    ///
    /// Named apart from [`OptionScalar::java_to_string`] (which every `OptionScalar` also gets
    /// through the blanket impl below) so that `x.java_to_string()` is not ambiguous when both
    /// traits are in scope.
    fn dyn_java_to_string(&self) -> String;
    /// `Some` iff this value is a Java `List`.
    fn as_list(&self) -> Option<&[Value]> {
        None
    }
}

impl<T: OptionScalar> OptionValue for T {
    fn as_any(&self) -> &dyn Any {
        self
    }
    fn dyn_eq(&self, other: &dyn OptionValue) -> bool {
        other.as_any().downcast_ref::<T>() == Some(self)
    }
    fn dyn_java_to_string(&self) -> String {
        OptionScalar::java_to_string(self)
    }
}

/// A Java `List` value (the result of list-valued converters and of `allowMultiple` options).
#[derive(Clone, Debug, Default)]
pub struct ListValue(pub Vec<Value>);

impl OptionValue for ListValue {
    fn as_any(&self) -> &dyn Any {
        self
    }
    fn dyn_eq(&self, other: &dyn OptionValue) -> bool {
        match other.as_list() {
            Some(o) => o == self.0.as_slice(),
            None => false,
        }
    }
    fn dyn_java_to_string(&self) -> String {
        java_list_to_string(self.0.iter().map(|v| v.java_to_string()))
    }
    fn as_list(&self) -> Option<&[Value]> {
        Some(&self.0)
    }
}

/// Java `AbstractCollection.toString`: `[a, b, c]`.
pub fn java_list_to_string(items: impl Iterator<Item = String>) -> String {
    let mut s = String::from("[");
    let mut first = true;
    for i in items {
        if !first {
            s.push_str(", ");
        }
        first = false;
        s.push_str(&i);
    }
    s.push(']');
    s
}

/// A type-erased, immutable option value. Equality is Java `equals`.
#[derive(Clone)]
pub struct Value(Arc<dyn OptionValue>);

impl Value {
    pub fn new<T: OptionScalar>(v: T) -> Value {
        Value(Arc::new(v))
    }
    pub fn list(values: Vec<Value>) -> Value {
        Value(Arc::new(ListValue(values)))
    }
    pub fn list_of<T: OptionScalar>(values: impl IntoIterator<Item = T>) -> Value {
        Value::list(values.into_iter().map(Value::new).collect())
    }
    pub fn downcast_ref<T: Any>(&self) -> Option<&T> {
        self.0.as_any().downcast_ref::<T>()
    }
    pub fn as_list(&self) -> Option<&[Value]> {
        self.0.as_list()
    }
    pub fn java_to_string(&self) -> String {
        self.0.dyn_java_to_string()
    }
    /// Convenience: the value as a `T`, panicking if it has a different type.
    pub fn get<T: Any + Clone>(&self) -> T {
        self.downcast_ref::<T>()
            .unwrap_or_else(|| panic!("value {:?} is not a {}", self.0, std::any::type_name::<T>()))
            .clone()
    }
}

impl PartialEq for Value {
    fn eq(&self, other: &Value) -> bool {
        self.0.dyn_eq(&*other.0)
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// Java `String.valueOf(Object)` for a nullable value.
pub fn java_string_of(v: Option<&Value>) -> String {
    match v {
        None => "null".to_string(),
        Some(v) => v.java_to_string(),
    }
}

// ---------------------------------------------------------------------------------------------
// Scalar implementations for the core types and a few common converter result types.

impl OptionScalar for String {
    fn java_to_string(&self) -> String {
        self.clone()
    }
}
impl OptionScalar for bool {
    fn java_to_string(&self) -> String {
        self.to_string()
    }
}
impl OptionScalar for i32 {
    fn java_to_string(&self) -> String {
        self.to_string()
    }
}
impl OptionScalar for i64 {
    fn java_to_string(&self) -> String {
        self.to_string()
    }
}
impl OptionScalar for f64 {
    fn java_to_string(&self) -> String {
        java_double_to_string(*self)
    }
}
impl OptionScalar for Duration {
    fn java_to_string(&self) -> String {
        java_duration_to_string(*self)
    }
}
/// `Map.Entry<String, String>` (e.g. `AssignmentConverter`). Java `toString` is `key=value`.
impl OptionScalar for (String, String) {
    fn java_to_string(&self) -> String {
        format!("{}={}", self.0, self.1)
    }
}
/// `Map.Entry<String, Double>` (`StringToDoubleAssignmentConverter`).
impl OptionScalar for (String, f64) {
    fn java_to_string(&self) -> String {
        format!("{}={}", self.0, java_double_to_string(self.1))
    }
}
/// `Map.Entry<String, List<String>>` (`StringToStringListConverter`).
impl OptionScalar for (String, Vec<String>) {
    fn java_to_string(&self) -> String {
        format!("{}={}", self.0, java_list_to_string(self.1.iter().cloned()))
    }
}

/// Java `Double.toString` for the common cases (integral values print with `.0`).
pub fn java_double_to_string(d: f64) -> String {
    if d.is_nan() {
        return "NaN".to_string();
    }
    if d.is_infinite() {
        return if d > 0.0 { "Infinity" } else { "-Infinity" }.to_string();
    }
    if d == d.trunc() && d.abs() < 1e7 {
        return format!("{:.1}", d);
    }
    let abs = d.abs();
    if (1e-3..1e7).contains(&abs) {
        format!("{}", d)
    } else {
        // Java uses computerized scientific notation, e.g. 1.0E-4.
        let s = format!("{:E}", d);
        match s.split_once('E') {
            Some((m, e)) if !m.contains('.') => format!("{}.0E{}", m, e),
            _ => s,
        }
    }
}

// Java: java/time/Duration.java Duration.toString (JDK), used by OptionsBase.asMap/cacheKey.
pub fn java_duration_to_string(d: Duration) -> String {
    if d.is_zero() {
        return "PT0S".to_string();
    }
    let effective_total_secs = d.as_secs();
    let nanos = d.subsec_nanos();
    let hours = effective_total_secs / 3600;
    let minutes = (effective_total_secs % 3600) / 60;
    let secs = effective_total_secs % 60;
    let mut buf = String::from("PT");
    if hours != 0 {
        buf.push_str(&format!("{}H", hours));
    }
    if minutes != 0 {
        buf.push_str(&format!("{}M", minutes));
    }
    if secs == 0 && nanos == 0 && buf.len() > 2 {
        return buf;
    }
    buf.push_str(&secs.to_string());
    if nanos > 0 {
        let frac = format!("{:09}", nanos);
        buf.push('.');
        buf.push_str(frac.trim_end_matches('0'));
    }
    buf.push('S');
    buf
}

/// `java.lang.Void`: options of this type carry no value (always Java `null`).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Void;

/// `java.util.OptionalInt`.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct OptionalInt(pub Option<i32>);

impl OptionScalar for OptionalInt {
    fn java_to_string(&self) -> String {
        match self.0 {
            Some(v) => format!("OptionalInt[{}]", v),
            None => "OptionalInt.empty".to_string(),
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Field types.

/// What `OptionDefinition.getType()` would report, as far as the parser cares.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FieldKind {
    /// Primitive `boolean` (not `java.lang.Boolean`).
    Boolean,
    TriState,
    Void,
    Other,
}

/// Error used when a value does not fit the field (Java's `IllegalArgumentException` from
/// `Field.set`).
#[derive(Debug)]
pub struct FieldTypeMismatch;

/// A Rust type usable as the type of an option field.
///
/// Mapping from Java field types (see `TRANSCRIBE.md`): `boolean`->`bool`, `int`->`i32`,
/// `long`->`i64`, `double`->`f64`, `String`->`String` (or `Option<String>` when the default is
/// `"null"`), `List<T>`->`Vec<T>`, `TriState`->`TriState`, `Duration`->`std::time::Duration`,
/// `Void`->`Void`, `Map.Entry<String,String>`->`(String, String)`.
pub trait FieldType: Sized + Clone + fmt::Debug + Send + Sync + 'static {
    const KIND: FieldKind = FieldKind::Other;
    /// `Class.isPrimitive()`.
    const IS_PRIMITIVE: bool = false;
    /// Whether the field can hold Java `null`.
    const NULLABLE: bool = false;
    /// Whether this is a `List<T>` field.
    const IS_LIST: bool = false;
    /// Member of `UsesOnlyCoreTypes.CORE_TYPES`.
    const IS_CORE_TYPE: bool = false;
    /// The Java type name, for messages (`Class.getName()`).
    const JAVA_TYPE_NAME: &'static str;

    /// `Converters.DEFAULT_CONVERTERS.get(getFieldSingularType())`.
    fn default_converter() -> Option<Arc<dyn Converter>> {
        None
    }
    fn from_value(v: Option<&Value>) -> Result<Self, FieldTypeMismatch>;
    fn to_value(&self) -> Option<Value>;
    /// The field's value in a freshly constructed (unparsed) instance.
    fn raw_default() -> Self;
    /// `Class.isEnum()` and `Class.getEnumConstants()` (each constant's `toString()`), for a
    /// field whose type is a Java enum; `None` otherwise.
    fn enum_constants() -> Option<Vec<String>> {
        None
    }
}

fn scalar_from<T: OptionScalar>(v: Option<&Value>) -> Result<T, FieldTypeMismatch> {
    v.and_then(|v| v.downcast_ref::<T>())
        .cloned()
        .ok_or(FieldTypeMismatch)
}

macro_rules! core_scalar_field {
    ($t:ty, $kind:expr, $prim:expr, $jname:expr, $conv:expr, $raw:expr) => {
        impl FieldType for $t {
            const KIND: FieldKind = $kind;
            const IS_PRIMITIVE: bool = $prim;
            const IS_CORE_TYPE: bool = true;
            const JAVA_TYPE_NAME: &'static str = $jname;
            fn default_converter() -> Option<Arc<dyn Converter>> {
                Some(Arc::new($conv))
            }
            fn from_value(v: Option<&Value>) -> Result<Self, FieldTypeMismatch> {
                scalar_from::<$t>(v)
            }
            fn to_value(&self) -> Option<Value> {
                Some(Value::new(self.clone()))
            }
            fn raw_default() -> Self {
                $raw
            }
        }
    };
}

core_scalar_field!(
    bool,
    FieldKind::Boolean,
    true,
    "boolean",
    converters::BooleanConverter,
    false
);
core_scalar_field!(
    i32,
    FieldKind::Other,
    true,
    "int",
    converters::IntegerConverter,
    0
);
core_scalar_field!(
    i64,
    FieldKind::Other,
    true,
    "long",
    converters::LongConverter,
    0
);
core_scalar_field!(
    f64,
    FieldKind::Other,
    true,
    "double",
    converters::DoubleConverter,
    0.0
);
core_scalar_field!(
    String,
    FieldKind::Other,
    false,
    "java.lang.String",
    converters::StringConverter,
    String::new()
);
core_scalar_field!(
    TriState,
    FieldKind::TriState,
    false,
    "com.google.devtools.common.options.TriState",
    converters::TriStateConverter,
    TriState::AUTO
);
core_scalar_field!(
    Duration,
    FieldKind::Other,
    false,
    "java.time.Duration",
    converters::DurationConverter,
    Duration::ZERO
);

impl FieldType for Void {
    const KIND: FieldKind = FieldKind::Void;
    const NULLABLE: bool = true;
    const IS_CORE_TYPE: bool = true;
    const JAVA_TYPE_NAME: &'static str = "java.lang.Void";
    fn default_converter() -> Option<Arc<dyn Converter>> {
        Some(Arc::new(converters::VoidConverter))
    }
    fn from_value(v: Option<&Value>) -> Result<Self, FieldTypeMismatch> {
        match v {
            None => Ok(Void),
            Some(_) => Err(FieldTypeMismatch),
        }
    }
    fn to_value(&self) -> Option<Value> {
        None
    }
    fn raw_default() -> Self {
        Void
    }
}

/// Implements [`FieldType`] for a converter result type that has no default converter (enums,
/// entries, custom value classes). The type must implement [`OptionScalar`].
///
/// `raw = expr` gives the placeholder held by a freshly constructed (unparsed) instance; it is
/// always overwritten by the parser (Java holds `null` there). Without it, `Default` is used.
#[macro_export]
macro_rules! option_field_type {
    (@impl $t:ty, $jname:expr, $raw:expr, $($extra:tt)*) => {
        impl $crate::FieldType for $t {
            const JAVA_TYPE_NAME: &'static str = $jname;
            fn from_value(
                v: ::core::option::Option<&$crate::Value>,
            ) -> ::core::result::Result<Self, $crate::value::FieldTypeMismatch> {
                v.and_then(|v| v.downcast_ref::<$t>())
                    .cloned()
                    .ok_or($crate::value::FieldTypeMismatch)
            }
            fn to_value(&self) -> ::core::option::Option<$crate::Value> {
                ::core::option::Option::Some($crate::Value::new(::core::clone::Clone::clone(self)))
            }
            fn raw_default() -> Self {
                // Placeholder until the parser sets the field; Java would hold `null` here.
                $raw
            }
            $($extra)*
        }
    };
    ($t:ty, $jname:expr) => {
        $crate::option_field_type!(
            $t,
            $jname,
            raw = <$t as ::core::default::Default>::default()
        );
    };
    ($t:ty, $jname:expr, raw = $raw:expr, enum) => {
        $crate::option_field_type!(@impl $t, $jname, $raw,
            fn enum_constants() -> ::core::option::Option<::std::vec::Vec<::std::string::String>> {
                ::core::option::Option::Some(
                    <$t as $crate::converters::JavaEnum>::values()
                        .iter()
                        .map(|v| $crate::OptionScalar::java_to_string(v))
                        .collect(),
                )
            }
        );
    };
    ($t:ty, $jname:expr, raw = $raw:expr) => {
        $crate::option_field_type!(@impl $t, $jname, $raw,);
    };
}

option_field_type!((String, String), "java.util.Map$Entry");
option_field_type!((String, f64), "java.util.Map$Entry");
option_field_type!((String, Vec<String>), "java.util.Map$Entry");
option_field_type!(OptionalInt, "java.util.OptionalInt");

/// Nullable wrapper: Java reference fields whose default is `"null"`.
impl<T: FieldType> FieldType for Option<T> {
    const KIND: FieldKind = T::KIND;
    const NULLABLE: bool = true;
    const IS_LIST: bool = T::IS_LIST;
    const IS_CORE_TYPE: bool = T::IS_CORE_TYPE && !T::IS_PRIMITIVE;
    const JAVA_TYPE_NAME: &'static str = T::JAVA_TYPE_NAME;
    fn default_converter() -> Option<Arc<dyn Converter>> {
        T::default_converter()
    }
    fn from_value(v: Option<&Value>) -> Result<Self, FieldTypeMismatch> {
        match v {
            None => Ok(None),
            Some(_) => T::from_value(v).map(Some),
        }
    }
    fn to_value(&self) -> Option<Value> {
        self.as_ref().and_then(|v| v.to_value())
    }
    fn raw_default() -> Self {
        None
    }
    fn enum_constants() -> Option<Vec<String>> {
        T::enum_constants()
    }
}

/// `List<T>`: either an `allowMultiple` option, or a converter that returns a list.
impl<T: FieldType> FieldType for Vec<T> {
    const IS_LIST: bool = true;
    const JAVA_TYPE_NAME: &'static str = "java.util.List";
    fn default_converter() -> Option<Arc<dyn Converter>> {
        // getFieldSingularType() is the element type for allowMultiple options; a non-multiple
        // List-typed field always needs an explicit converter (checked by OptionProcessor).
        T::default_converter()
    }
    fn from_value(v: Option<&Value>) -> Result<Self, FieldTypeMismatch> {
        let list = v.and_then(|v| v.as_list()).ok_or(FieldTypeMismatch)?;
        list.iter().map(|e| T::from_value(Some(e))).collect()
    }
    fn to_value(&self) -> Option<Value> {
        Some(Value::list(
            self.iter()
                .map(|e| e.to_value().expect("null element in a List option value"))
                .collect(),
        ))
    }
    fn raw_default() -> Self {
        Vec::new()
    }
}
